import ast
import os
import sys

def analyze_file(filepath):
    with open(filepath, 'r', encoding='utf-8') as f:
        content = f.read()

    try:
        tree = ast.parse(content, filename=filepath)
    except SyntaxError:
        print(f"Syntax error in {filepath}")
        return

    # To get source lines easily
    lines = content.splitlines()

    class FuncVisitor(ast.NodeVisitor):
        def visit_FunctionDef(self, node):
            # Check if legacy_auth is called in this function
            calls_legacy = False
            for child in ast.walk(node):
                if isinstance(child, ast.Call):
                    if isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                        calls_legacy = True
                        break

            if calls_legacy:
                # Find start and end lines of the function
                start_line = node.lineno - 1
                # To find end line, we can estimate or use the last child's lineno
                end_line = start_line
                for child in ast.walk(node):
                    if hasattr(child, 'lineno'):
                        end_line = max(end_line, child.lineno)

                func_src = "\n".join(lines[start_line:end_line])

                # Check for write/mutation keywords in the function body
                keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]
                # We can also check function name, docstring, etc.
                matched_kws = [kw for kw in keywords if kw in func_src]
                # Let's also check if the file path has any of these words
                matched_filepath = [kw for kw in keywords if kw in filepath]

                print(f"FILE: {filepath} | FUNC: {node.name} (lines {node.lineno}-{end_line})")
                print(f"Matched in Src: {matched_kws}")
                print(f"Matched in Filepath: {matched_filepath}")
                print("SOURCE:")
                print(func_src)
                print("-" * 40)

    FuncVisitor().visit(tree)

def main():
    for root, dirs, files in os.walk('.'):
        if 'node_modules' in dirs:
            dirs.remove('node_modules')
        if '.git' in dirs:
            dirs.remove('.git')
        for file in files:
            if file.endswith('.py') and file != 'list_sites.py' and file != 'auth.py':
                filepath = os.path.join(root, file)
                # Read content to check if 'legacy_auth' is in it
                with open(filepath, 'r', encoding='utf-8') as f:
                    if 'legacy_auth' in f.read():
                        analyze_file(filepath)

if __name__ == '__main__':
    main()

