import ast
import os
import re

def analyze():
    keywords = ["create_", "update_", "delete_", "save_", "write_", "POST", "PUT", "PATCH"]
    # We also want to check case-insensitive versions or word fragments just in case
    pattern = re.compile(r"create_|update_|delete_|save_|write_|POST|PUT|PATCH", re.IGNORECASE)

    for root, dirs, files in os.walk('.'):
        if 'node_modules' in dirs: dirs.remove('node_modules')
        if '.git' in dirs: dirs.remove('.git')
        for file in files:
            if file.endswith('.py') and file not in ('check_matches.py', 'list_sites.py', 'auth.py'):
                filepath = os.path.join(root, file)
                with open(filepath, 'r') as f:
                    content = f.read()
                if 'legacy_auth' not in content:
                    continue

                try:
                    tree = ast.parse(content, filepath)
                except Exception as e:
                    print(f"Error parsing {filepath}: {e}")
                    continue

                lines = content.splitlines()
                for node in ast.walk(tree):
                    if isinstance(node, ast.FunctionDef):
                        # Check if legacy_auth is inside this function
                        calls_legacy = False
                        for child in ast.walk(node):
                            if isinstance(child, ast.Call) and isinstance(child.func, ast.Name) and child.func.id == 'legacy_auth':
                                calls_legacy = True
                                break
                        if not calls_legacy:
                            continue

                        start = node.lineno - 1
                        end = start
                        for child in ast.walk(node):
                            if hasattr(child, 'lineno'):
                                end = max(end, child.lineno)
                        func_src = "\n".join(lines[start:end])

                        # Find exact prompt keyword matches (case sensitive and case insensitive)
                        exact_matches_sensitive = [kw for kw in keywords if kw in func_src]
                        exact_matches_insensitive = [kw for kw in keywords if kw.lower() in func_src.lower()]

                        filepath_matches = [kw for kw in keywords if kw.lower() in filepath.lower()]

                        print(f"File: {filepath} | Func: {node.name}")
                        print(f"  Exact Sensitive: {exact_matches_sensitive}")
                        print(f"  Exact Insensitive: {exact_matches_insensitive}")
                        print(f"  Filepath matches: {filepath_matches}")
                        print(f"  Src fragment: {func_src.replace('\n', '  |  ')}")
                        print()

if __name__ == '__main__':
    analyze()

